import{_ as o}from"./chunks/page-selection.ClIk5vyj.js";import{_ as a,o as r,c as s,a2 as e}from"./chunks/framework.CfwCq2QB.js";const l="/dev-go-docs/shots/0.2.3/manual/selection-panel.png",n="/dev-go-docs/shots/0.2.3/zh-CN/light/options-selection.png",f=JSON.parse('{"title":"划词工具条与自定义动作","description":"","frontmatter":{},"headers":[],"relativePath":"features/selection-toolbar.md","filePath":"features/selection-toolbar.md"}'),i={name:"features/selection-toolbar.md"};function g(c,t,h,d,p,u){return r(),s("div",null,[...t[0]||(t[0]=[e('<h1 id="划词工具条与自定义动作" tabindex="-1">划词工具条与自定义动作 <a class="header-anchor" href="#划词工具条与自定义动作" aria-label="Permalink to &quot;划词工具条与自定义动作&quot;">​</a></h1><p>一句话：选中网页文字，上方浮出工具条——翻译、解释、总结、问 AI；在输入框里选中文字可以用 AI 润色、纠错、改正式并一键替换原文。</p><h2 id="网页文字上" tabindex="-1">网页文字上 <a class="header-anchor" href="#网页文字上" aria-label="Permalink to &quot;网页文字上&quot;">​</a></h2><p>选中文字后浮出的工具条：</p><ul><li><strong>翻译</strong>：翻译选中文本；选中单个英文单词时，同时显示词典释义</li><li><strong>解释 / 总结</strong>：AI 结合所在段落和网页标题解释、提炼选中内容</li><li><strong>问 AI</strong>：打开侧边栏，带着选中内容继续追问</li><li>动作超过 4 个时收进「更多」下拉菜单</li></ul><img src="'+o+'" alt="划词工具条"><p>结果面板贴在选中文字下方，页面滚动时跟着走；可以点图钉<strong>固定</strong>在屏幕上，也可以拖动。底部支持<strong>复制、继续追问、重试</strong>。</p><img src="'+l+'" alt="划词「解释」的结果面板：顶部可切换翻译 / 解释 / 总结，正文是 AI 的解释结果，底部有继续追问、复制等操作"><h2 id="输入框里" tabindex="-1">输入框里 <a class="header-anchor" href="#输入框里" aria-label="Permalink to &quot;输入框里&quot;">​</a></h2><p>在输入框（评论框、搜索框、网页编辑器）里选中文字，工具条变成写作模式：<strong>润色、纠错、正式</strong>，以及你添加的适用范围包含「输入框」的自定义动作。AI 处理完点「替换原文」，输入框内容直接替换成结果。</p><h2 id="自定义动作" tabindex="-1">自定义动作 <a class="header-anchor" href="#自定义动作" aria-label="Permalink to &quot;自定义动作&quot;">​</a></h2><p>内置动作不够用时，在设置页「划词 → 工具条动作 → 新增动作」添加：</p><ul><li><strong>名称</strong>：显示在工具条上，如「译成英文」</li><li><strong>图标</strong>：从 12 个常用图标里选</li><li><strong>适用范围</strong>：网页文字 / 输入框 / 两者都适用</li><li><strong>提示词</strong>：告诉 AI 怎么处理选中内容，如「把选中的内容整理成 JSON，只输出 JSON 本身」</li></ul><p>不用自己拼上下文——和内置动作一样，请求会自动附带选中内容所在的段落和网页标题。</p><p>自带三个示例模板，一键添加：<strong>译成英文</strong>、<strong>解释报错</strong>、<strong>转 JSON</strong>。</p><p>管理区还支持：编辑、删除（有确认）、上移 / 下移排序，内置动作也可以逐个隐藏。工具条最多直接显示 4 个动作，其余收进「更多」。</p><img src="'+n+'" alt="划词设置"><h2 id="开关与停用" tabindex="-1">开关与停用 <a class="header-anchor" href="#开关与停用" aria-label="Permalink to &quot;开关与停用&quot;">​</a></h2><ul><li><strong>全局开关</strong>：设置页「划词 → 启用划词」；「AI 动作」也可以单独关掉（只留翻译）</li><li><strong>按网站停用</strong>：弹窗「功能」页 →「划词工具条」开关只管当前网站，关掉后提示「已在 xxx 停用」；停用列表在设置页「停用划词的网站」里管理</li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>解释、总结等 AI 动作需要先配置<a href="/dev-go-docs/settings/models.html">对话模型</a>（未单独配置时沿用翻译模型）</li><li>只想关掉某一个网站（比如在线编辑器）时，用按站停用，不用关全局</li><li>自定义动作参与<a href="/dev-go-docs/settings/sync.html">备份导出 / 导入</a>，换机不丢</li></ul>',21)])])}const b=a(i,[["render",g]]);export{f as __pageData,b as default};
